// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');

// Query tabs (.agent/execplan-query-tabs-g2.md): several queries open side by side on one repository's Query page,
// each with its own text and result, kept across a reload.

const workbenchBase = process.env.RDF4J_WORKBENCH_BASE_URL || 'http://127.0.0.1:8080/rdf4j-workbench';
const serverBase = process.env.RDF4J_SERVER_BASE_URL || 'http://127.0.0.1:8080/rdf4j-server';
const repositoryId = process.env.RDF4J_E2E_QUERY_TABS_REPOSITORY || 'e2e-query-tabs';

const tabs = (page) => page.locator('#query-tabs [role="tab"]');
const selectedTab = (page) => page.locator('#query-tabs [role="tab"][aria-selected="true"]');

const STATEMENTS = `@prefix ex: <http://example.org/> .
ex:a a ex:Thing ; ex:label "a" . ex:b a ex:Thing ; ex:label "b" . ex:c a ex:Other ; ex:label "c" .`;

/** The spec's repository with exactly its six statements (an in-memory store loses them when the server restarts). */
async function ensureRepository(request) {
    const existing = await request.get(`${serverBase}/repositories/${repositoryId}/size`);
    if (existing.ok() && (await existing.text()).trim() === '6') {
        return;
    }
    if (!existing.ok()) {
        const config = `@prefix config: <tag:rdf4j.org,2023:config/> .
[] a config:Repository ;
   config:rep.id "${repositoryId}" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ;
       config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ] .`;
        const created = await request.put(`${serverBase}/repositories/${repositoryId}`, {
            headers: { 'Content-Type': 'text/turtle' }, data: config
        });
        expect(created.ok(), `create repository ${repositoryId}: ${created.status()}`).toBeTruthy();
    }
    const loaded = await request.put(`${serverBase}/repositories/${repositoryId}/statements`, {
        headers: { 'Content-Type': 'text/turtle' }, data: STATEMENTS
    });
    expect(loaded.ok(), `load statements: ${loaded.status()}`).toBeTruthy();
}

async function setEditorText(page, text) {
    await page.evaluate((value) => {
        const editor = document.querySelector('#query-page .CodeMirror');
        // @ts-ignore CodeMirror instance hangs off its wrapper element
        editor.CodeMirror.setValue(value);
    }, text);
}

async function runAndWaitForBadge(page, text) {
    await setEditorText(page, text);
    const executions = [];
    const listener = (request) => {
        if (request.method() === 'POST' && (request.postData() || '').includes('action=exec')) {
            executions.push(request.url());
        }
    };
    page.on('request', listener);
    await page.click('#exec');
    await expect(selectedTab(page).locator('.query-tabs__badge')).toBeVisible({ timeout: 30000 });
    page.off('request', listener);
    expect(executions.length).toBe(1);
    return selectedTab(page).locator('.query-tabs__badge').textContent();
}

test.describe('Query tabs', () => {
    test.beforeEach(async ({ page, request }) => {
        await ensureRepository(request);
        await page.goto(`${workbenchBase}/repositories/${repositoryId}/query`);
        await expect(tabs(page)).toHaveCount(1);
        // A clean slate: forget the tabs and pages an earlier run left in this browser profile.
        await page.evaluate(() => {
            for (const storage of [localStorage, sessionStorage]) {
                Object.keys(storage).filter((key) => key.startsWith('rdf4j.workbench.query.tabs.v2:')
                    || key.startsWith('rdf4j.workbench.workspace.v1:')).forEach((key) => storage.removeItem(key));
            }
        });
        await page.reload();
        await expect(tabs(page)).toHaveCount(1);
    });

    test('the tab row is the island\'s top part and the editor sits flush under it', async ({ page }) => {
        const row = page.locator('#query-tabs');
        const form = page.locator('#query-form');
        // The editor's surface: its wrapper reaches the card edges; CodeMirror sits inside its padding.
        const editor = page.locator('#query-primary-pane .yasqe');
        const rowBox = await row.boundingBox();
        const formBox = await form.boundingBox();
        const editorBox = await editor.boundingBox();
        expect(Math.abs(rowBox.y - formBox.y)).toBeLessThan(2);
        expect(Math.abs(rowBox.x - formBox.x)).toBeLessThan(2);
        expect(Math.abs(editorBox.x - formBox.x)).toBeLessThan(2);
        expect(Math.abs(editorBox.width - formBox.width)).toBeLessThan(3);
        expect(editorBox.y).toBeGreaterThanOrEqual(rowBox.y + rowBox.height - 1);
        await expect(page.locator('#query-page')).toHaveClass(/query-page--tabs/);
        await expect(page.locator('#query-primary-pane .query-editor-header')).toBeHidden();
    });

    test('two tabs keep their own text and result; switching back shows rows without re-running', async ({ page }) => {
        const first = await runAndWaitForBadge(page,
            'PREFIX ex: <http://example.org/>\nSELECT ?t WHERE { ?t a ex:Thing }');
        expect(first).toBe('2');
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('SELECT ?t WHERE { ?t a ex:Thing }');

        await page.click('#query-tabs .query-tabs__new');
        await expect(tabs(page)).toHaveCount(2);
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('Untitled query');
        const second = await runAndWaitForBadge(page,
            'PREFIX ex: <http://example.org/>\nSELECT ?label WHERE { ?s ex:label ?label }');
        expect(second).toBe('3');
        await expect(page.locator('#query-results')).toContainText('3 rows');

        const executions = [];
        page.on('request', (request) => {
            if (request.method() === 'POST' && (request.postData() || '').includes('action=exec')) {
                executions.push(request.url());
            }
        });
        await tabs(page).first().click();
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('SELECT ?t WHERE { ?t a ex:Thing }');
        await expect(page.locator('#query-results')).toContainText('2 rows');
        await expect(page.locator('#query-results-count')).toHaveText('2');
        expect(executions.length).toBe(0);

        await page.reload();
        await expect(tabs(page)).toHaveCount(2);
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('SELECT ?t WHERE { ?t a ex:Thing }');
        await expect(tabs(page).nth(0).locator('.query-tabs__badge')).toHaveText('2');
        await expect(tabs(page).nth(1).locator('.query-tabs__badge')).toHaveText('3');
    });

    test('a reload shows the saved result again without asking the server', async ({ page }) => {
        await runAndWaitForBadge(page, 'PREFIX ex: <http://example.org/>\nSELECT ?t WHERE { ?t a ex:Thing }');
        await expect.poll(() => page.evaluate(() => {
            const key = Object.keys(sessionStorage).find((name) => name.startsWith('rdf4j.workbench.query.tabs.v2:'));
            const state = key ? JSON.parse(sessionStorage.getItem(key)) : null;
            return state && state.tabs[0].lastRun && state.tabs[0].lastRun.saved ? state.tabs[0].lastRun.saved.rows : null;
        }), { timeout: 10000 }).toBe(2);
        const executions = [];
        page.on('request', (request) => {
            if (request.method() === 'POST' && (request.postData() || '').includes('action=exec')) {
                executions.push(request.url());
            }
        });
        await page.reload();
        await expect(page.locator('#query-results')).toContainText('2 rows', { timeout: 15000 });
        await expect(page.locator('#query-results')).toContainText('ex:a');
        expect(executions.length).toBe(0);
    });

    test('a saved result older than 15 minutes says how long ago its query ran', async ({ page }) => {
        await runAndWaitForBadge(page, 'PREFIX ex: <http://example.org/>\nSELECT ?t WHERE { ?t a ex:Thing }');
        await expect.poll(() => page.evaluate(() => Object.keys(sessionStorage).some((name) =>
            name.startsWith('rdf4j.workbench.query.tabs.v2:') && sessionStorage.getItem(name).includes('"saved":{')
        )), { timeout: 10000 }).toBe(true);
        // As if the query ran two hours ago: the saved result keeps when it ran.
        await page.evaluate(() => {
            for (const storage of [localStorage, sessionStorage]) {
                const key = Object.keys(storage).find((name) => name.startsWith('rdf4j.workbench.query.tabs.v2:'));
                const state = JSON.parse(storage.getItem(key));
                const before = Date.now() - 2 * 60 * 60 * 1000 - 60000;
                state.tabs[0].lastRun.at = before;
                state.tabs[0].lastRun.saved.ranAt = before;
                storage.setItem(key, JSON.stringify(state));
            }
        });
        await page.reload();
        await expect(page.locator('#query-results')).toContainText('ran 2 h ago', { timeout: 15000 });
        await page.click('#query-tabs .query-tabs__menu-button');
        await expect(page.locator('#query-tabs .query-tabs__menu-meta').first()).toContainText('ran 2 h ago');
    });

    test('switching repositories opens one as it was left, and Undo can start it afresh', async ({ page, request }) => {
        const other = repositoryId + '-other';
        const exists = await request.get(`${serverBase}/repositories/${other}/size`);
        if (!exists.ok()) {
            const created = await request.put(`${serverBase}/repositories/${other}`, {
                headers: { 'Content-Type': 'text/turtle' }, data: `@prefix config: <tag:rdf4j.org,2023:config/> .
[] a config:Repository ; config:rep.id "${other}" ;
   config:rep.impl [ config:rep.type "openrdf:SailRepository" ; config:sail.impl [ config:sail.type "openrdf:MemoryStore" ] ] .`
            });
            expect(created.ok()).toBeTruthy();
        }
        await runAndWaitForBadge(page, 'PREFIX ex: <http://example.org/>\nSELECT ?t WHERE { ?t a ex:Thing }');
        await page.click('#query-tabs .query-tabs__new');
        await setEditorText(page, 'ASK { ?s ?p ?o }');

        // Over to the other repository with the switcher, then back.
        await page.goto(`${workbenchBase}/repositories/${other}/summary`);
        await page.click('#workbench-repository-switcher, [aria-controls="workbench-repository-panel"]');
        await page.locator(`a.workbench-popover__option[data-repository-id="${repositoryId}"]`).click();
        await expect(page).toHaveURL(new RegExp(`/repositories/${repositoryId}/query`), { timeout: 15000 });
        await expect(tabs(page)).toHaveCount(2);
        const toast = page.locator('.workbench-toast');
        await expect(toast).toContainText(`Restored ${repositoryId} as you left it: Query page, 2 query tabs.`);

        await toast.locator('.workbench-toast__action').click();
        const dialog = page.locator('dialog.workbench-dialog--choice');
        await expect(dialog).toBeVisible();
        await dialog.locator('[data-choice="empty"]').click();
        await expect(page).toHaveURL(new RegExp(`/repositories/${repositoryId}/summary`), { timeout: 15000 });
        await page.goto(`${workbenchBase}/repositories/${repositoryId}/query`);
        await expect(tabs(page)).toHaveCount(1);
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('Untitled query');
    });

    test('a failed query marks its tab; closing tabs falls back to a neighbour and finally to one empty tab', async ({ page }) => {
        await setEditorText(page, 'SELECT ?x WHERE { ?x <http://example.org/broken> ');
        await page.click('#exec');
        await expect(selectedTab(page).locator('.query-tabs__dot--error')).toBeVisible({ timeout: 30000 });

        await page.click('#query-tabs .query-tabs__new');
        await expect(tabs(page)).toHaveCount(2);
        await tabs(page).first().hover();
        await tabs(page).first().locator('.query-tabs__close').click();
        await expect(tabs(page)).toHaveCount(1);
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('Untitled query');

        await setEditorText(page, 'ASK { ?s ?p ?o }');
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('ASK { ?s ?p ?o }');
        await selectedTab(page).locator('.query-tabs__close').click();
        await expect(tabs(page)).toHaveCount(1);
        await expect(selectedTab(page).locator('.query-tabs__title')).toHaveText('Untitled query');
        expect(await page.evaluate(() => document.querySelector('#query-page .CodeMirror').CodeMirror.getValue())).toBe('');
    });
});
